    # Base cases for the first three Tribonacci numbers
    tri_sequence = [1, 3, 2]
    if n < 3:
        return tri_sequence[:n + 1]

    # Calculate the rest of the Tribonacci sequence
    for i in range(3, n + 1):
        if i % 2 == 0:
            tri_sequence.append(tri(i - 1) + tri(i + 1))
        else:
            tri_sequence.append(tri(i - 1) + tri(i - 2) + tri(i + 1))

